/*
 * Purpose:
 * Find the first triangular number that has more than 500 divisors.
 *
 * Approach:
 * A triangular number is generated by summing the natural numbers:
 *
 *     T_n = 1 + 2 + 3 + ... + n
 *
 * The program first generates a list of prime numbers using the
 * Sieve of Eratosthenes. These primes are then used to determine
 * the number of divisors of each triangular number.
 *
 * For each triangular number:
 *   1. Generate the next triangular number.
 *   2. Factorise the number using the precomputed prime list.
 *   3. Determine the exponent of each prime factor.
 *   4. Use the divisor-count formula
 *
 *          (a + 1)(b + 1)(c + 1)...
 *
 *      where a, b, c, ... are the exponents of the prime factors.
 *   5. Check whether the divisor count exceeds 500.
 *
 * The search continues until a triangular number with more than
 * 500 divisors is found, after which the number is printed.
 *
 * This approach is considerably faster than checking every possible
 * divisor directly because it relies on prime factorisation to
 * calculate the divisor count.
 */

#include <cstdlib>
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int main(int argc, char** argv) {
    // Target number of divisors.
    int nDivisors = 500;

    // Variables used to generate successive triangular numbers.
    int number = 1;
    int triangleNumber = 0;

    // Indicates whether the solution has been found.
    bool fin = false;
    
    // Sieve representation of odd numbers.
    bool primes[5000];
    for(int i = 0; i < 5000; i++) {
        primes[i] = true;
    }
    
    // Generate a list of primes using a variation of the
    // Sieve of Eratosthenes.
    vector<int> primeList;
    primeList.push_back(2);
    for(int i = 1; i < 5000; i++) {
        if(primes[i] == true) {
            // Convert sieve index into the corresponding odd number.
            int temp = i * 2 + 1;

            // Mark multiples as composite.
            for(int j = i + temp; j < 5000; j+=temp) {
                primes[j] = false;
            }
            primeList.push_back(temp);
        }
    }
    int count = 0;
    while(!fin) {
        // Generate the next triangular number.
        triangleNumber += number;

        // Working copy used during factorisation.
        int triangleNumber_factor = triangleNumber;
        number++;
        
        // Accumulate the divisor count using the formula
        // (a+1)(b+1)(c+1)...
        int divisors = 1;
        int limit = sqrt(triangleNumber);

        // Factorise the triangular number using the prime list.
        for(int i = 0, j = primeList[i]; i < primeList.size() && j < limit; i++, j = primeList[i]) {
            // Count the exponent of the current prime factor.
            int thisPrimeDivisors = 0;
            while (triangleNumber_factor % j == 0)  {
                thisPrimeDivisors++;
                triangleNumber_factor /= j;
            }

            // Incorporate this prime's contribution to the
            // total number of divisors.
            divisors = divisors * (thisPrimeDivisors + 1);
        }

        // If a prime factor remains, its exponent is 1 and
        // therefore contributes a factor of 2.
        if (triangleNumber_factor != 1) {
            divisors = divisors * 2;
        }

        // Stop once a triangular number with more than
        // the required number of divisors is found.
        if(nDivisors < divisors) {
            fin = true;
        }
    }
    
    // Output the first triangular number with over 500 divisors.
    cout << triangleNumber;
    return 0;
}

